import collections
import six

PARAMETERS_SECTION = 'parameters'
RESOURCE_REGISTRY_SECTION = 'resource_registry'


def merge_map(old, new, deep_merge_enabled, merge_strings_enabled):
    """Merge nested dictionaries."""
    if not old:
        return new

    for k, v in new.items():
        _merge_parameter(old, k, v, deep_merge_enabled, merge_strings_enabled)

    return old


def _merge_list(old, new):
    """Merge lists and comma delimited lists."""
    if not old:
        return new

    if isinstance(new, list):
        old.extend(new)
        return old
    else:
        return ','.join([old, new])


def _is_mapping(v):
    return isinstance(v, collections.Mapping)


def _is_sequence_and_not_string(v):
    return isinstance(v, collections.Sequence) and not isinstance(
        v, six.string_types)


def _is_string(v):
    return isinstance(v, six.string_types)


def _is_integer(v):
    isinstance(v, int)


def _merge_mapping(old, k, v, deep_merge_enabled, merge_strings_enabled):
    old_v = old.get(k)
    old[k] = merge_map(old_v, v, deep_merge_enabled,
                       merge_strings_enabled) if old_v else v


def _merge_sequence(old, k, v):
    old_v = old.get(k)
    old[k] = _merge_list(old_v, v) if old_v else v


def _merge_string(old, k, v):
    old[k] = ''.join([old.get(k, ''), v])


def _merge_integer(old, k, v):
    old[k] = v + old.get(k, 0)


def _merge_parameter(old, k, v, deep_merge_enabled, merge_strings_enabled):
    if not deep_merge_enabled and k not in (PARAMETERS_SECTION, RESOURCE_REGISTRY_SECTION):
        old[k] = v
    elif _is_mapping(v):
        _merge_mapping(old, k, v, deep_merge_enabled, merge_strings_enabled)
    elif _is_sequence_and_not_string(v):
        _merge_sequence(old, k, v)
    elif _is_string(v) and merge_strings_enabled:
        _merge_string(old, k, v)
    elif _is_integer(v):
        _merge_integer(old, k, v)
    else:
        old[k] = v
